#!/bin/bash
#
# Regression tests on synthetic PDFs (string and name scanner, options and exit codes).
#
# Usage:
#   ./test_pdf_sintetici.sh [EXECUTABLE] [--options]
#
#   EXECUTABLE  default: MY_PDF_SEARCH_EXE (see common_paths.sh)
#   --options   also checks the options --show_errors and --show_warnings
#               and the exit codes (0 ok, 1 fatal error, 2 files with errors)
#               (--opzioni and --avviso are accepted aliases)
#
# The PDFs are generated by this script (python3 is required) in a temporary
# directory that is removed at the end. The error log
# (AAA_mypdfsearch_parsing_errors.txt) is created in the same temporary
# directory, so it does not pollute the directory the script is run from.
#
# Exit status: 0 = all tests passed, 1 = at least one test failed,
#              2 = setup error.

SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)" || exit 2
source "$SCRIPT_DIR/common_paths.sh"

EXE="$MY_PDF_SEARCH_EXE"
CHECK_WARN=0
for a in "$@"; do
	case "$a" in
		--options|--opzioni|--avviso) CHECK_WARN=1 ;;
		*)        EXE="$a" ;;
	esac
done
EXE="$(my_pdf_resolve_exe "$EXE")"

if [ ! -x "$EXE" ]; then
	echo "Executable not found or not executable: $EXE"
	exit 2
fi
if ! command -v python3 >/dev/null 2>&1; then
	echo "python3 not found: it is needed to generate the test PDFs."
	exit 2
fi

WORK=$(mktemp -d) || exit 2
trap 'rm -rf "$WORK"' EXIT
cd "$WORK" || exit 2

python3 - "$WORK" <<'PY'
import sys

def build(path, content, fontname=b"F1"):
    objs = []
    objs.append(b"<< /Type /Catalog /Pages 2 0 R >>")
    objs.append(b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>")
    objs.append(b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 4 0 R"
                b" /Resources << /Font << /" + fontname + b" 5 0 R >> >> >>")
    objs.append(b"<< /Length %d >>\nstream\n" % len(content) + content + b"\nendstream")
    objs.append(b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>")
    out = b"%PDF-1.4\n"
    offs = []
    for i, o in enumerate(objs, 1):
        offs.append(len(out))
        out += b"%d 0 obj\n" % i + o + b"\nendobj\n"
    x = len(out)
    out += b"xref\n0 %d\n0000000000 65535 f \n" % (len(objs) + 1)
    for o in offs:
        out += b"%010d 00000 n \n" % o
    out += b"trailer\n<< /Size %d /Root 1 0 R >>\nstartxref\n%d\n%%%%EOF\n" % (len(objs) + 1, x)
    open(path, "wb").write(out)

d = sys.argv[1]

# S9/S10: octal escapes of 1 or 2 digits followed by a normal character
build(d + "/oct_short.pdf",
      b"BT /F1 12 Tf 10 700 Td (a\\53bcd) Tj 0 -20 Td (x\\7yz) Tj 0 -20 Td (m\\101nop) Tj ET")

# S9/S10: short octal escapes followed by ')' (end of the string)
build(d + "/oct_close.pdf",
      b"BT /F1 12 Tf 10 700 Td (first\\53) Tj 0 -20 Td (second) Tj 0 -20 Td (third\\7) Tj"
      b" 0 -20 Td (fourth) Tj ET")

# S5: name with #xx whose second hexadecimal digit is a lowercase letter a-e
build(d + "/name_hex.pdf",
      b"BT /F#6a 12 Tf 10 700 Td (hello name) Tj ET", b"F#6a")

# Nested balanced parentheses, escaped parentheses, empty string
build(d + "/paren_nested.pdf",
      b"BT /F1 12 Tf 10 700 Td (a(b)c) Tj 0 -20 Td (x(y(z)w)v) Tj 0 -20 Td (p\\(q) Tj"
      b" 0 -20 Td (m\\)n) Tj 0 -20 Td (f(x) = 3) Tj 0 -20 Td () Tj 0 -20 Td (end) Tj ET")

# ExtGState with /Font [object size]: 'gs' changes the current font
def build_gs(path, gsdict, content):
    objs = [b"<< /Type /Catalog /Pages 2 0 R >>",
            b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
            b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 4 0 R"
            b" /Resources << /Font << /F1 5 0 R >> /ExtGState << /GS1 6 0 R >> >> >>",
            b"<< /Length %d >>\nstream\n" % len(content) + content + b"\nendstream",
            b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>",
            gsdict,
            b"<< /Type /Font /Subtype /Type1 /BaseFont /Times-Roman /Encoding /WinAnsiEncoding >>"]
    out = b"%PDF-1.4\n"
    offs = []
    for i, o in enumerate(objs, 1):
        offs.append(len(out))
        out += b"%d 0 obj\n" % i + o + b"\nendobj\n"
    x = len(out)
    out += b"xref\n0 %d\n0000000000 65535 f \n" % (len(objs) + 1)
    for o in offs:
        out += b"%010d 00000 n \n" % o
    out += b"trailer\n<< /Size %d /Root 1 0 R >>\nstartxref\n%d\n%%%%EOF\n" % (len(objs) + 1, x)
    open(path, "wb").write(out)

gs_content = (b"BT /F1 12 Tf 10 700 Td (one) Tj ET\n/GS1 gs\nBT 10 650 Td (two) Tj ET\n"
              b"BT /F1 12 Tf 10 600 Td (three) Tj ET")
build_gs(d + "/gs_font.pdf", b"<< /Type /ExtGState /Font [7 0 R 14] >>", gs_content)
build_gs(d + "/gs_font_real.pdf", b"<< /Type /ExtGState /Font [7 0 R 12.5] /LW 2 /CA 0.5 >>", gs_content)
build_gs(d + "/gs_font_key_first.pdf", b"<< /LW 2 /Font [7 0 R 12] /D [[3] 0] >>", gs_content)
build_gs(d + "/gs_font_nested.pdf",
         b"<< /Type /ExtGState /SMask << /Type /Mask /S /Alpha >> /Font [7 0 R 12] >>", gs_content)

# For --show_errors: a file that is not a PDF
open(d + "/not_a_pdf.pdf", "wb").write(b"this is not a PDF\n")

# For --show_warnings: stream closed by 'endobj' instead of 'endstream'
data = open(d + "/oct_short.pdf", "rb").read()
i = data.find(b"endstream")
open(d + "/no_endstream.pdf", "wb").write(data[:i] + data[i + len(b"endstream"):])
PY

if [ $? -ne 0 ]; then
	echo "Error generating the test PDFs."
	exit 2
fi

PASS=0
FAIL=0

# check NAME EXPECTED_LINE...   (every expected line must appear in full in the output)
check() {
	local name="$1"; shift
	local ok=1 line out

	rm -f "$WORK/AAA_mypdfsearch_parsing_errors.txt"
	out=$("$EXE" --extracttextfrom="$WORK/$name.pdf" 2>"$WORK/$name.err" | sed 's/[[:space:]]*$//')

	for line in "$@"; do
		if ! printf '%s\n' "$out" | grep -Fxq -- "$line"; then
			echo "    missing line: '$line'"
			ok=0
		fi
	done

	if [ -s "$WORK/AAA_mypdfsearch_parsing_errors.txt" ]; then
		echo "    the parser wrote errors to the log:"
		sed 's/^/      /' "$WORK/AAA_mypdfsearch_parsing_errors.txt" | head -6
		ok=0
	fi

	if [ -s "$WORK/$name.err" ]; then
		echo "    stderr is not empty:"
		sed 's/^/      /' "$WORK/$name.err" | head -3
		ok=0
	fi

	if [ $ok -eq 1 ]; then
		echo "PASS: $name"
		PASS=$((PASS + 1))
	else
		echo "FAIL: $name"
		echo "    output obtained:"
		printf '%s\n' "$out" | sed -n '/TEXT EXTRACTED/,$p' | sed 's/^/      /' | head -12
		FAIL=$((FAIL + 1))
	fi
}

echo "=============================================================="
echo "SYNTHETIC PDF TESTS - mypdfsearch"
echo "Executable: $EXE"
echo "=============================================================="

check oct_short    "TEXT EXTRACTED FROM PAGE 1:" "a+bcd" "xyz" "mAnop"
check oct_close    "TEXT EXTRACTED FROM PAGE 1:" "first+" "second" "third" "fourth"
check name_hex     "TEXT EXTRACTED FROM PAGE 1:" "hello name"
check paren_nested "TEXT EXTRACTED FROM PAGE 1:" "a(b)c" "x(y(z)w)v" "p(q" "m)n" "f(x) = 3" "end"
check gs_font          "TEXT EXTRACTED FROM PAGE 1:" "one" "two" "three"
check gs_font_real     "TEXT EXTRACTED FROM PAGE 1:" "one" "two" "three"
check gs_font_key_first "TEXT EXTRACTED FROM PAGE 1:" "one" "two" "three"
check gs_font_nested   "TEXT EXTRACTED FROM PAGE 1:" "one" "two" "three"

# result NAME CONDITION_OK [DETAIL]
result() {
	if [ "$2" -eq 1 ]; then
		echo "PASS: $1"
		PASS=$((PASS + 1))
	else
		echo "FAIL: $1"
		[ -n "$3" ] && echo "    $3"
		FAIL=$((FAIL + 1))
	fi
}

# stderr_of FILE [OPTIONS...]  -> prints the stderr of the run
stderr_of() {
	local f="$1"; shift
	rm -f "$WORK/AAA_mypdfsearch_parsing_errors.txt"
	"$EXE" "$@" --extracttextfrom="$WORK/$f" 2>&1 >/dev/null
}

# exit_code_of ARGUMENTS...  -> prints the exit code of the run
exit_code_of() {
	( cd "$WORK" && "$EXE" "$@" >/dev/null 2>&1 </dev/null; echo $? )
}

if [ $CHECK_WARN -eq 1 ]; then
	# exit codes
	rc=$(exit_code_of --extracttextfrom="$WORK/oct_short.pdf")
	result "exit code 0: valid PDF" $([ "$rc" = 0 ] && echo 1 || echo 0) "obtained: $rc"

	rc=$(exit_code_of --extracttextfrom="$WORK/not_a_pdf.pdf")
	result "exit code 2: file that is not a PDF" $([ "$rc" = 2 ] && echo 1 || echo 0) "obtained: $rc"

	rc=$(exit_code_of --extracttextfrom="$WORK/missing.pdf")
	result "exit code 2: nonexistent file" $([ "$rc" = 2 ] && echo 1 || echo 0) "obtained: $rc"

	rc=$(exit_code_of --version)
	result "exit code 0: --version" $([ "$rc" = 0 ] && echo 1 || echo 0) "obtained: $rc"

	rc=$(exit_code_of --no_such_option)
	result "exit code 1: unknown option" $([ "$rc" = 1 ] && echo 1 || echo 0) "obtained: $rc"

	# file that is not a PDF: errors
	e=$(stderr_of not_a_pdf.pdf)
	result "no options: no message on stderr" $([ -z "$e" ] && echo 1 || echo 0) "stderr: ${e:0:200}"

	e=$(stderr_of not_a_pdf.pdf --show_errors)
	result "--show_errors: ERRORS summary on stderr" $(echo "$e" | grep -q "^ERRORS (" && echo 1 || echo 0) "stderr: ${e:0:200}"
	result "--show_errors: error log created" $([ -s "$WORK/AAA_mypdfsearch_parsing_errors.txt" ] && echo 1 || echo 0)

	e=$(stderr_of not_a_pdf.pdf --show_warnings)
	result "--show_warnings: no ERRORS summary" $(echo "$e" | grep -q "ERRORS" && echo 0 || echo 1) "stderr: ${e:0:200}"

	# stream closed by endobj: warning
	e=$(stderr_of no_endstream.pdf)
	result "no options: no message (file with warnings)" $([ -z "$e" ] && echo 1 || echo 0) "stderr: ${e:0:200}"

	e=$(stderr_of no_endstream.pdf --show_warnings)
	result "--show_warnings: WARNING summary on stderr" $(echo "$e" | grep -q "^WARNING (" && echo 1 || echo 0) "stderr: ${e:0:200}"

	e=$(stderr_of no_endstream.pdf --show_errors)
	result "--show_errors: no WARNING summary" $(echo "$e" | grep -q "WARNING" && echo 0 || echo 1) "stderr: ${e:0:200}"

	# valid PDF: no message even with both options
	e=$(stderr_of oct_short.pdf --show_errors --show_warnings)
	result "valid PDF: no message with both options" $([ -z "$e" ] && echo 1 || echo 0) "stderr: ${e:0:200}"
fi

echo "=============================================================="
echo "PASS: $PASS   FAIL: $FAIL"
echo "=============================================================="

[ $FAIL -eq 0 ]
